&lt;/td&gt;&lt;td width=&quot;17%&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
&lt;/td&gt;&lt;td width=&quot;17%&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
&lt;/td&gt;&lt;td width=&quot;21%&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d&#39;objets magiques&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;br /&gt;&lt;b&gt; Caract&#233;ristique associ&#233;e&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Formation n&#233;cessaire&lt;/b&gt; : oui&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Le personnage sait comment s’y prendre avec les animaux et peut leur enseigner des tours, les faire ob&#233;ir &#224; des ordres simples ou m&#234;me les apprivoiser.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Test de comp&#233;tence&lt;a class=&quot;headeranchor&quot; id=&quot;Test_de_comp&#233;tence_0&quot; href=&quot;#Test_de_comp&#233;tence_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du test d&#233;pend du r&#233;sultat que le personnage d&#233;sire obtenir.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Tests de Dressage&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;T&#226;che&lt;/td&gt;&lt;td&gt;DD du test de Dressage&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;diriger un animal&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;pousser un animal&lt;/td&gt;&lt;td&gt;25&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;enseigner un tour &#224; un animal&lt;/td&gt;&lt;td&gt;15 ou 20*&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;enseigner une fonction &#224; un animal&lt;/td&gt;&lt;td&gt;15 ou 20*&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&#233;lever un animal sauvage&lt;/td&gt;&lt;td&gt;15 + &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de l’animal&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;note&quot;&gt;&lt;i&gt;(*) Reportez-vous &#224; la description du tour ou de la fonction en question ci-dessous.&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Diriger un animal.&lt;/b&gt; Cela consiste &#224; ordonner &#224; un animal d’effectuer une t&#226;che ou un tour de son r&#233;pertoire. Si l’animal est bless&#233; ou s’il a subi des &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Nonletal.html&quot; title=&quot;D&#233;g&#226;ts non l&#233;taux&quot;&gt;d&#233;g&#226;ts non l&#233;taux&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement de caract&#233;ristique&quot;&gt;affaiblissement de caract&#233;ristique&lt;/a&gt;, le DD est augment&#233; de +2. Si le personnage r&#233;ussit son test, l’animal ex&#233;cute la t&#226;che ou le tour demand&#233; lors de sa prochaine action.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pousser un animal.&lt;/b&gt; Cela permet de pousser un animal &#224; accomplir une t&#226;che ou un tour auquel il n’est pas entra&#238;n&#233; mais dont il est physiquement capable. Cela inclut aussi la marche forc&#233;e ou le footing pendant plus d’une heure entre deux cycles de sommeil. Si l’animal est bless&#233; ou s’il a subi des &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Nonletal.html&quot; title=&quot;D&#233;g&#226;ts non l&#233;taux&quot;&gt;d&#233;g&#226;ts non l&#233;taux&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement de caract&#233;ristique&quot;&gt;affaiblissement de caract&#233;ristique&lt;/a&gt;, le DD est augment&#233; de +2. Si le personnage r&#233;ussit son test, l’animal ex&#233;cute la t&#226;che ou le tour demand&#233; lors de sa prochaine action.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Enseigner des tours &#224; un animal.&lt;/b&gt; Un personnage a besoin d’une semaine de travail (et d’un test de Dressage) pour apprendre un tour sp&#233;cifique &#224; un animal. Les animaux ayant une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de 1 peuvent apprendre jusqu’&#224; trois tours au maximum, tandis que les animaux ayant une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de 2 peuvent assimiler jusqu’&#224; six tours. Voici les tours les plus courants (et le DD qui leur est associ&#233;).&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot; WIDTH=&quot;98%&quot;&gt;&lt;caption&gt;Tours les plus courants&lt;/caption&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Arr&#234;te ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot; WIDTH=&quot;80%&quot;&gt;L’animal arr&#234;te de se battre ou de faire autre chose. Un animal qui ne conna&#238;t pas ce tour continue &#224; lutter jusqu’&#224; ce qu’il soit contraint de fuir (&#224; cause de blessures ou d’un effet de terreur par exemple) ou que son adversaire soit vaincu.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Attaque ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal attaque les cr&#233;atures qu’il assimile &#224; des ennemis. Le personnage peut indiquer du doigt une cible pr&#233;cise, que l’animal attaquera s’il le peut. Normalement, un animal n’attaque que les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;des&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de-Monstrueux.html&quot; title=&quot;Humano&#239;de monstrueux&quot;&gt;humano&#239;des monstrueux&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-G&#233;ant.html&quot; title=&quot;G&#233;ant (sous-type)&quot;&gt;g&#233;ants&lt;/a&gt; et les autres animaux. Apprendre &#224; un animal &#224; attaquer les cr&#233;atures de tous types (y compris des cr&#233;atures surnaturelles comme les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Aberration.html&quot; title=&quot;Aberration&quot;&gt;aberrations&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt;) &#233;quivaut &#224; deux tours.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Attends ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal ne bouge pas et attend le retour de son ma&#238;tre. Il n’attaque pas les cr&#233;atures qui s’approchent de lui mais se d&#233;fend si n&#233;cessaire.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Au pied ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal suit fid&#232;lement son ma&#238;tre, m&#234;me si cela l’oblige &#224; se rendre dans un lieu qui lui d&#233;pla&#238;t.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Cherche ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal gagne l’endroit d&#233;sign&#233; et y cherche quelque chose de vivant ou de mobile.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Garde ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal ne bouge pas et emp&#234;che quiconque d’approcher.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Joue ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal conna&#238;t une s&#233;rie de tours basiques, comme s’asseoir, se coucher sur le dos, donner la patte, gronder, aboyer sur demande et ainsi de suite.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Prot&#232;ge ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal prot&#232;ge son ma&#238;tre (ou se pr&#233;pare &#224; le d&#233;fendre si aucune menace n’est visible) sans que celui-ci ait besoin de le lui ordonner. Il peut aussi lui demander de prot&#233;ger quelqu’un d’autre.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Suis ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal suit la piste olfactive qu’on lui montre (cela suppose que l’animal poss&#232;de la particularit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;odorat&quot;&gt;odorat&lt;/a&gt;).&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Travaille ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal peut tracter ou pousser une charge interm&#233;diaire ou lourde.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;&#171; Va chercher ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal va chercher quelque chose. Si son ma&#238;tre ne lui d&#233;signe pas l’objet &#224; rapporter, l’animal en prend un au hasard.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;&#171; Viens ! &#187;&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L’animal rejoint son ma&#238;tre, m&#234;me s’il ne le ferait pas en temps normal.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Dons-Et-Comp&#233;tences).html#13&quot; title=&quot;FAQ du Manuel des joueurs, section dons et comp&#233;tences&quot;&gt;→&lt;/a&gt; Dressage : Entra&#238;ner un animal avec Dressage pour en faire une Monture de combat (p.97 dans le Manuel des joueurs) lui conf&#232;re-t-il Porte des armures l&#233;g&#232;res ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non, utiliser &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;&lt;/u&gt; pour entra&#238;ner un animal ou une monture de cette fa&#231;on ne lui offre pas un don suppl&#233;mentaire gratuit. En revanche, il n’est pas d&#233;raisonnable de consid&#233;rer qu’un animal con&#231;u sp&#233;cifiquement pour &#234;tre mont&#233; (comme un &lt;a class=&quot;pagelink&quot; href=&quot;Cheval.html&quot; title=&quot;Cheval&quot;&gt;cheval&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Chien.html&quot; title=&quot;Chien&quot;&gt;chien&lt;/a&gt;) puisse &#234;tre achet&#233; avec &lt;a class=&quot;pagelink&quot; href=&quot;Port-Des-Armures-L&#233;g&#232;res.html&quot; title=&quot;Port des armures l&#233;g&#232;res&quot;&gt;Port des armures l&#233;g&#232;res&lt;/a&gt; dans sa liste de dons (rempla&#231;ant respectivement Endurance ou Talent) pour le m&#234;me prix.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;b&gt;Enseigner une fonction &#224; un animal.&lt;/b&gt; Plut&#244;t que d’apprendre des tours un par un, il est possible d’entra&#238;ner un animal &#224; remplir une fonction particuli&#232;re. Chaque fonction regroupe une s&#233;rie de tours qui correspondent &#224; un th&#232;me donn&#233;, comme monter la garde ou participer au travail. L’animal doit remplir toutes les conditions des tours regroup&#233;s par cette la fonction. Si une fonction comprend plus de trois tours, elle est r&#233;serv&#233;e aux animaux ayant une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#233;gale ou sup&#233;rieure &#224; 2.&lt;br /&gt;&lt;br /&gt;On ne peut apprendre qu’une seule fonction &#224; un animal, mais il peut apprendre des tours suppl&#233;mentaires (en plus de ceux compris dans sa fonction) s’il est assez intelligent pour cela. Entra&#238;ner un animal &#224; une fonction demande moins de tests de Dressage, mais autant de temps que de lui apprendre les tours qui la composent un par un.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot; WIDTH=&quot;98%&quot;&gt;&lt;caption&gt;Fonctions les plus courantes&lt;/caption&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;Animal de chasse&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot; WIDTH=&quot;80%&quot;&gt;Un animal entra&#238;n&#233; pour la chasse conna&#238;t les tours arr&#234;te, attaque, au pied, cherche, suis et va chercher. Entra&#238;ner un animal pour devenir un animal de chasse prend six semaines.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;Animal de combat&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; &#224; se battre conna&#238;t les tours arr&#234;te, attaque et attends. Entra&#238;ner un animal de combat prend trois semaines.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;Animal de foire&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; pour la foire conna&#238;t les tours attends, au pied, joue, va chercher et viens. Entra&#238;ner un animal un animal de foire prend cinq semaines.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;Animal de garde&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; &#224; monter la garde conna&#238;t les tours arr&#234;te, attaque, garde et prot&#232;ge. Entra&#238;ner un animal de garde prend quatre semaines.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;Monture&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; &#224; servir de monture conna&#238;t les tours attends, au pied et viens. Entra&#238;ner une monture prend trois semaines.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;b&gt;Monture de combat&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 20&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; &#224; servir de monture de combat conna&#238;t les tours arr&#234;te, attaque, au pied, garde, prot&#232;ge et viens. Entra&#238;ner une monture de combat prend six semaines. Entra&#238;ner un animal poss&#233;dant d&#233;j&#224; la fonction monture pour en faire une monture de combat ne prend que trois semaines (et un test de Dressage DD 20). La nouvelle fonction et le nouveau r&#233;pertoire de tours remplacent les pr&#233;c&#233;dents. La plupart des destriers et les chiens de selle ont re&#231;u ce type d’entra&#238;nement.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;b&gt;Travailleur de force&lt;/b&gt;&lt;/td&gt;&lt;td&gt;DD 15&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Un animal entra&#238;n&#233; au travail conna&#238;t les tours travaille et viens. Entra&#238;ner un travailleur de force prend deux semaines.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&#201;lever un animal sauvage.&lt;/b&gt; Il s’agit d’&#233;lever une cr&#233;ature sauvage qui vient de na&#238;tre pour en faire un animal domestique. Au maximum, le personnage peut s’occuper de trois animaux du m&#234;me type &#224; la fois.&lt;br /&gt;&lt;br /&gt;Si le test de comp&#233;tence est r&#233;ussi, l’animal peut apprendre des tours (soit en m&#234;me temps pendant qu’il grandit, soit plus tard comme un animal domestique).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Action&lt;a class=&quot;headeranchor&quot; id=&quot;Action_1&quot; href=&quot;#Action_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
Variable. Diriger un animal est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; et pousser un animal est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; (un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; peut diriger son &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;compagnon animal&quot;&gt;compagnon animal&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; et le pousser par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;). Dans le cas des t&#226;ches pour lesquelles une dur&#233;e est indiqu&#233;e, le personnage doit passer la moiti&#233; du temps indiqu&#233; (&#224; raison de trois heures par jour et par animal entra&#238;n&#233;) avant d’effectuer son &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Testsdecompetences.html&quot; title=&quot;test de comp&#233;tence&quot;&gt;test de comp&#233;tence&lt;/a&gt;. En cas d’&#233;chec, il ne parvient pas &#224; dresser ou &#224; mater l’animal, ni &#224; lui enseigner le moindre tour, mais il n’a pas &#224; finir le dressage ou l’&#233;levage. Si le test est r&#233;ussi, il faut encore accorder &#224; l’animal le reste du temps n&#233;cessaire pour que le dressage (ou autre) soit couronn&#233; de succ&#232;s. En cas d’interruption ou si le personnage n’ach&#232;ve pas la t&#226;che fix&#233;e, toute tentative faite par la suite pour dresser, mater ou apprendre des tours &#224; l’animal &#233;choue automatiquement.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Nouvelles tentatives&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_tentatives_2&quot; href=&quot;#Nouvelles_tentatives_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
Oui, sauf pour &#233;lever un animal sauvage.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Sp&#233;cial&lt;a class=&quot;headeranchor&quot; id=&quot;Sp&#233;cial_3&quot; href=&quot;#Sp&#233;cial_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
On peut utiliser cette comp&#233;tence sur une cr&#233;ature ayant une valeur d’Intelligence de 1 ou 2 et qui n’est pas un animal, mais le DD de la t&#226;che augmente de +5. Le nombre de tours que ces cr&#233;atures peuvent apprendre est limit&#233; de la m&#234;me fa&#231;on que pour les animaux.&lt;br /&gt;&lt;br /&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; obtient un bonus de circonstances de +4 aux tests de Dressage li&#233;s &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;compagnon animal&quot;&gt;compagnon animal&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;De plus, le &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;compagnon animal&quot;&gt;compagnon animal&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ou d’un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; conna&#238;t un (ou plusieurs) tours suppl&#233;mentaires, qui ne comptent pas dans la limite normale des tours qu’un animal peut apprendre et qui ne n&#233;cessitent aucun temps de dressage.&lt;br /&gt;&lt;br /&gt;Un personnage poss&#233;dant le don &lt;a class=&quot;pagelink&quot; href=&quot;Fraternit&#233;-Animale.html&quot; title=&quot;Fraternit&#233; animale&quot;&gt;Fraternit&#233; animale&lt;/a&gt; obtient un bonus aux tests de Dressage.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Utilisation sans formation&lt;a class=&quot;headeranchor&quot; id=&quot;Utilisation_sans_formation_4&quot; href=&quot;#Utilisation_sans_formation_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
Un personnage ayant un rang nul en Dressage peut diriger ou pousser les animaux domestiques en r&#233;ussissant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;, mais il ne peut ni dresser, ni &#233;lever d’animaux. Un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; ayant un rang nul en Dressage peut effectuer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour diriger ou pousser son &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;compagnon animal&quot;&gt;compagnon animal&lt;/a&gt; mais il ne peut ni dresser, ni &#233;lever d’autres animaux non-domestiqu&#233;s.
